import os, json, sys
sys.path.append('storage/shared/atlas/tools')
import ci_validate

base = 'storage/shared/atlas/edges/aether/renewal_maturity_edge'
entry = f'{base}/entry.json'
need = [
  f'{base}/pre/hinge_metrics.csv', f'{base}/pre/hinge_summary.txt', f'{base}/pre/boundary_panel.png',
  f'{base}/post/hinge_metrics.csv', f'{base}/post/hinge_summary.txt', f'{base}/post/boundary_panel.png',
  f'{base}/renewal_summary.txt'
]

curated = 'storage/shared/atlas/edges/index.json'
def load_idx(p):
    try:
        with open(p,'r',encoding='utf-8') as f: return json.load(f)
    except Exception:
        return {"entries": []}
def norm(ents):
    out=[]
    for e in ents:
        if isinstance(e, dict) and "entry_path" in e: out.append({"entry_path": e["entry_path"]})
        elif isinstance(e, dict) and "path" in e:     out.append({"entry_path": e["path"]})
        elif isinstance(e, str):                      out.append({"entry_path": e})
    return out

ents = norm(load_idx(curated).get("entries", []))
before = set(e["entry_path"] for e in ents)
updates = []
if os.path.exists(entry) and all(os.path.exists(p) for p in need) and entry not in before:
    ents.append({"entry_path": entry}); updates.append({"added": entry})
    ents = sorted(ents, key=lambda x: x["entry_path"])
    with open(curated,'w',encoding='utf-8') as f:
        json.dump({"entries": ents}, f, ensure_ascii=False, indent=2)

out = ci_validate.run()
print(json.dumps({"status":"ok","updates":updates,"entries_found": out.get("entries_found"), "ok": out.get("ok"), "with_errors": out.get("with_errors")}))
